{
  "name": "树莓派硬件SPI接口",
  "name_en": "Raspberry Pi Hardware SPI Interface",
  "manufacturer": "",
  "description": "树莓派板载的硬件 SPI 总线接口，通过 GPIO 排针与支持 SPI 的外设进行同步串行通信，常用于实验室原型开发、传感器与 ADC/DAC 连接，以及小型仪器控制与数据采集。",
  "description_en": "The onboard hardware SPI bus interface of a Raspberry Pi, exposed through the GPIO header for synchronous serial communication with SPI peripherals. It is commonly used in labs for prototyping, connecting sensors and ADCs/DACs, and for small instrument control and data acquisition.",
  "tag_hints": [
    "Raspberry Pi GPIO",
    "hardware SPI",
    "SPI peripheral communication",
    "embedded prototyping",
    "sensor interfacing",
    "data acquisition"
  ],
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭 SPI 连接",
      "description_en": "Close the SPI connection."
    },
    {
      "action_name": "auto-transfer",
      "description": "通过 SPI 传输数据",
      "description_en": "Transfer data over SPI."
    },
    {
      "action_name": "auto-closed",
      "description": "获取 SPI 连接是否已关闭",
      "description_en": "Get whether the SPI connection is closed."
    },
    {
      "action_name": "auto-connection",
      "description": "获取与 GPIO 守护进程的连接",
      "description_en": "Get the connection to the GPIO daemon."
    },
    {
      "action_name": "auto-host",
      "description": "获取 GPIO 守护进程主机地址",
      "description_en": "Get the GPIO daemon host address."
    },
    {
      "action_name": "auto-port",
      "description": "获取 GPIO 守护进程端口",
      "description_en": "Get the GPIO daemon port."
    },
    {
      "action_name": "auto-spi",
      "description": "获取 SPI 接口信息",
      "description_en": "Get the SPI interface information."
    },
    {
      "action_name": "auto-ticks",
      "description": "获取滴答计数值",
      "description_en": "Get the tick count value."
    },
    {
      "action_name": "auto-ticks_diff",
      "description": "计算两个滴答计数之间的时间差",
      "description_en": "Calculate the time difference between two tick counts."
    }
  ]
}

